"""Collect final frozen tests, actual CLI media, commands and original failures."""
from datetime import datetime,timezone
from pathlib import Path
import hashlib,json,re,shutil,subprocess
root=Path(__file__).resolve().parents[2];runtime=root/'product/.runtime';out=root/'docs/validation/evidence'
def load(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p):return 'sha256:'+hashlib.sha256(p.read_bytes()).hexdigest()
verification={mode:load(runtime/f'text-animation-accepted-v2-{mode}-20261017.json') for mode in ('full','targeted','before')}
full,target,before=[verification[k] for k in ('full','targeted','before')]
assert full['status']=='passed' and full['test_count']==524 and full['frozen_file_count']==99
assert target['status']=='passed' and target['test_count']==18
assert before['test_count']==18 and before['exit_code']==1 and before['failure_records']==28
for item in verification.values():assert item['frozen_before']==item['frozen_after']==full['frozen_after']
for name,digest in full['frozen_after'].items():assert sha(root/name)==digest,name
public=load(root/'docs/assets/text-animation-20261017/evidence.json');audit=load(runtime/'text-animation-independent-20261017.json')
assert public['frozen_before']==public['frozen_after']==full['frozen_after']
assert audit['public_evidence_sha256']==sha(root/'docs/assets/text-animation-20261017/evidence.json')
assert public['generator_sha256']==sha(root/'scripts/smoke_text_animation.py')
assert public['baseline_ref']==before['baseline_ref']=='68006af9e7b3ea26efc697ab2871fad7bf22bf94'
methods=set(re.findall(r'^    def (test_\w+)\(', (root/'product/tests/test_text_animation_composition.py').read_text(encoding='utf-8-sig'),re.M))
failures=set(re.findall(r'^(?:FAIL|ERROR): (test_\w+)',(runtime/'text-animation-accepted-v2-before-20261017.log').read_text(encoding='utf-8-sig'),re.M))
assert len(methods)==18 and methods==failures
assert len(public['records'])==12 and sum(r['full_delivery_verified'] for r in public['records'].values())==11
assert [name for name,r in public['records'].items() if not r['full_delivery_verified']]==['typing-nested-trim']
counts={key:sum(c['args'][0]==key for c in public['calls']) for key in ('project','media','timeline','render','quality','policy')}
assert len(public['calls'])==160 and counts['render']==50 and counts['quality']==counts['policy']==12
assert all(c['exit_code']==0 for c in public['calls'])
assert audit['new_main_frames']==846 and audit['control_frames']==1818
logs={}
for path in sorted(runtime.glob('text-animation-*-20261017.log')):
 if path.name=='text-animation-accepted-v4-media-20261017.log':
  name='text-animation-media-20261017.log'
 elif path.name=='text-animation-accepted-v3-media-20261017.log':
  name='text-animation-pre-cache-media-20261017.log'
 elif path.name=='text-animation-accepted-v2-media-20261017.log':
  name='text-animation-second-media-20261017.log'
 elif path.name=='text-animation-accepted-media-20261017.log':
  name='text-animation-initial-media-20261017.log'
 elif path.name.startswith('text-animation-accepted-v2-'):
  name=path.name.replace('text-animation-accepted-v2-','text-animation-')
 elif path.name.startswith('text-animation-accepted-'):
  name=path.name.replace('text-animation-accepted-','text-animation-initial-')
 else:name=path.name
 destination=out/name
 if destination.exists():assert destination.read_bytes()==path.read_bytes(),name
 else:shutil.copyfile(path,destination)
 logs[name]={'sha256':sha(destination),'bytes':destination.stat().st_size}
